active.nft:
table inet routeguard {
 set blocked4 { type ipv4_addr; flags interval; auto-merge; elements = { 192.0.2.10/32 }; }
 chain forward { type filter hook forward priority -1; policy accept;
  oifname { "wan" } ip daddr @blocked4 counter drop comment "forward4"
 }
 chain output { type filter hook output priority -1; policy accept;
  oifname { "wan" } ip daddr @blocked4 counter drop comment "output4"
 }
}
